// ฟังก์ชันช่วยเหลือสำหรับ filter ข้อมูล

/**
 * ดึงรายการอำเภอตามรหัสจังหวัด
 * @param provinceCode - รหัสจังหวัด (เช่น 10 = กรุงเทพฯ, 11 = สมุทรปราการ)
 * @returns Array ของอำเภอในจังหวัดนั้น
 */
export const getDistrictsByProvinceCode = (provinceCode: number): District[] => {
  return districts.filter((d) => d.provinceCode === provinceCode)
}

/**
 * ดึงรายการตำบลตามรหัสอำเภอ
 * @param districtCode - รหัสอำเภอ (เช่น 1001 = พระนคร)
 * @returns Array ของตำบลในอำเภอนั้น
 */
export const getSubDistrictsByDistrictCode = (districtCode: number): SubDistrict[] => {
  return subDistricts.filter((sd) => sd.districtCode === districtCode)
}

/**
 * ดึงรหัสไปรษณีย์จากรหัสตำบล
 * @param subdistrictCode - รหัสตำบล (เช่น 100101)
 * @returns รหัสไปรษณีย์
 */
export const getPostalCodeBySubDistrictCode = (subdistrictCode: number): number => {
  const subDistrict = subDistricts.find((sd) => sd.code === subdistrictCode)
  return subDistrict?.postalCode || 0
}

/**
 * ค้นหาจังหวัดจากชื่อ (ภาษาไทย)
 * @param name - ชื่อจังหวัด
 * @returns Province หรือ undefined
 */
export const findProvinceByName = (name: string): Province | undefined => {
  return provinces.find((p) => p.nameTh === name || p.nameEn === name)
}

/**
 * ค้นหาอำเภอจากชื่อและรหัสจังหวัด
 * @param name - ชื่ออำเภอ
 * @param provinceCode - รหัสจังหวัด
 * @returns District หรือ undefined
 */
export const findDistrictByName = (
  name: string,
  provinceCode: number
): District | undefined => {
  return districts.find(
    (d) => d.provinceCode === provinceCode && (d.nameTh === name || d.nameEn === name)
  )
}

/**
 * ค้นหาตำบลจากชื่อและรหัสอำเภอ
 * @param name - ชื่อตำบล
 * @param districtCode - รหัสอำเภอ
 * @returns SubDistrict หรือ undefined
 */
export const findSubDistrictByName = (
  name: string,
  districtCode: number
): SubDistrict | undefined => {
  return subDistricts.find(
    (sd) => sd.districtCode === districtCode && (sd.nameTh === name || sd.nameEn === name)
  )
}

/**
 * ค้นหาพื้นที่จากรหัสไปรษณีย์
 * @param postalCode - รหัสไปรษณีย์
 * @returns Array ของตำบลที่ตรงกับรหัสไปรษณีย์
 */
export const findByPostalCode = (postalCode: number): SubDistrict[] => {
  return subDistricts.filter((sd) => sd.postalCode === postalCode)
}
